===CustomerCode===
package org.springframework.samples.petclinic.util;

import java.util.Collection;

/**
 * The owner customer-code format, {@code <REGION>-<HASH8>}: the canonical region (see
 * {@link CityLocality}) followed by the first eight upper-case hex characters of a
 * SHA-256 fingerprint. This class owns the format so the two concerns that depend on it
 * — composing the code at creation and reading the region back out for locality — stay
 * in step.
 */
public final class CustomerCode {

    private static final char SEPARATOR = '-';

    private CustomerCode() {
    }

    /**
     * Composes a customer code from its region and hash components.
     *
     * @param region the canonical region
     * @param hash8  the eight-character hash
     * @return the {@code <REGION>-<HASH8>} customer code
     */
    public static String of(String region, String hash8) {
        return region + SEPARATOR + hash8;
    }

    /**
     * De-duplicates a customer code against the codes already in use. If the code is
     * unused it is returned unchanged; otherwise {@code -<n>} is appended with the
     * smallest {@code n} of two or more that yields a code not already taken.
     *
     * @param customerCode the composed customer code
     * @param existing     the customer codes already in use
     * @return the {@code customerCode}, or a {@code <customerCode>-<n>} variant unique
     *         among {@code existing}
     */
    public static String deduplicate(String customerCode, Collection<String> existing) {
        String candidate = customerCode;
        for (int n = 2; existing.contains(candidate); n++) {
            candidate = customerCode + SEPARATOR + n;
        }
        return candidate;
    }

    /**
     * The region component of a customer code, i.e. the part before the first separator.
     *
     * @param customerCode a customer code, or {@code null}
     * @return the region, or {@code null} when the code is absent or has no region part
     */
    public static String regionOf(String customerCode) {
        if (customerCode == null) {
            return null;
        }
        int separator = customerCode.indexOf(SEPARATOR);
        return separator > 0 ? customerCode.substring(0, separator) : null;
    }
}
===LuhnCheckDigit===
package org.springframework.samples.petclinic.util;

/**
 * Computes the Luhn check digit over the digits contained in a string. Non-digit
 * characters are ignored, so the algorithm applies unchanged to formatted values such as
 * an owner's customer code ({@code NSW-1A2B3C4D}).
 *
 * <p>Walking right to left, every second digit (starting with the rightmost) is doubled,
 * casting out nines, and the check digit is the amount needed to bring the running total
 * to a multiple of ten.
 */
public final class LuhnCheckDigit {

    private LuhnCheckDigit() {
    }

    /**
     * @param value the string whose digits are checked (non-digits are ignored)
     * @return the Luhn check digit, {@code 0}-{@code 9}
     */
    public static int of(String value) {
        int sum = 0;
        boolean doubling = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int digit = c - '0';
            if (doubling) {
                digit *= 2;
                if (digit > 9) {
                    digit -= 9;
                }
            }
            sum += digit;
            doubling = !doubling;
        }
        return (10 - (sum % 10)) % 10;
    }
}
===FiscalYear===
package org.springframework.samples.petclinic.util;

import java.time.LocalDate;

/**
 * The fiscal-year basis for date-derived owner values. The fiscal year starts on 1 July,
 * so a date in July&ndash;December belongs to the fiscal year ending the following
 * calendar year, and a date in January&ndash;June to the fiscal year ending that same
 * year. This class owns the definition so every fiscal-year-derived value &mdash; the
 * {@code fiscalYear} label, the membership number's year segment and tenure in elapsed
 * fiscal years &mdash; stays in step.
 */
public final class FiscalYear {

    /** The first month of a fiscal year (1 July). */
    private static final int START_MONTH = 7;

    private FiscalYear() {
    }

    /**
     * The fiscal year a date falls in, identified by the calendar year it ends in: the
     * date's own year for January&ndash;June, or the next year for July&ndash;December.
     *
     * @param date the date to classify
     * @return the ending calendar year of the containing fiscal year
     */
    public static int of(LocalDate date) {
        return date.getMonthValue() >= START_MONTH ? date.getYear() + 1 : date.getYear();
    }

    /**
     * The {@code FY<YY>} label for a date's fiscal year, where {@code <YY>} is the last two
     * digits of its {@link #of(LocalDate) ending year} (e.g. {@code FY26}).
     *
     * @param date the date to label
     * @return the fiscal-year label
     */
    public static String labelOf(LocalDate date) {
        return String.format("FY%02d", shortYearOf(date));
    }

    /**
     * The last two digits of a date's {@link #of(LocalDate) fiscal year}, for use as a
     * year segment (e.g. {@code 26}).
     *
     * @param date the date
     * @return the two-digit fiscal year
     */
    public static int shortYearOf(LocalDate date) {
        return of(date) % 100;
    }

    /**
     * The number of whole fiscal years elapsed between two dates: the difference between
     * their {@link #of(LocalDate) fiscal years}, never negative for a {@code from} on or
     * before {@code to}.
     *
     * @param from the earlier date
     * @param to   the later date
     * @return the count of fiscal years elapsed
     */
    public static int elapsed(LocalDate from, LocalDate to) {
        return of(to) - of(from);
    }
}
===Sha256===
package org.springframework.samples.petclinic.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * SHA-256 hashing rendered as hexadecimal. Kept separate from any one caller so the
 * digest algorithm is defined once and reused wherever a stable hex fingerprint of a
 * string is needed (e.g. the hash component of an owner's customer code).
 */
public final class Sha256 {

    private Sha256() {
    }

    /**
     * The first {@code length} upper-case hexadecimal characters of the SHA-256 digest of
     * the UTF-8 bytes of {@code value}.
     *
     * @param value  the string to hash
     * @param length the number of leading hex characters to return
     * @return {@code length} upper-case hex characters
     */
    public static String upperHexPrefix(String value, int length) {
        byte[] digest = digest(value);
        StringBuilder hex = new StringBuilder(length);
        for (int i = 0; hex.length() < length; i++) {
            hex.append(String.format(Locale.ROOT, "%02X", digest[i]));
        }
        return hex.substring(0, length);
    }

    /**
     * The full SHA-256 digest of the UTF-8 bytes of {@code value} rendered as 64 lower-case
     * hexadecimal characters.
     *
     * @param value the string to hash
     * @return 64 lower-case hex characters
     */
    public static String lowerHex(String value) {
        byte[] digest = digest(value);
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            hex.append(String.format(Locale.ROOT, "%02x", b));
        }
        return hex.toString();
    }

    private static byte[] digest(String value) {
        try {
            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
        }
    }
}
===OwnerSegment===
package org.springframework.samples.petclinic.util;

import java.util.Set;

/**
 * Classifies an owner into a market segment formatted {@code <TIER>_<AREA>}, one of
 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
 * {@code STANDARD_REGIONAL}.
 *
 * <p>The tier is {@code PREMIUM} when the membership level is 3 or more, otherwise
 * {@code STANDARD}. The area is {@code METRO} when the locality is a known region
 * (NSW, VIC or QLD), otherwise {@code REGIONAL}. This class owns only that
 * classification, keeping it separate from how the membership level and locality are
 * derived (see {@link CityLocality}).
 */
public final class OwnerSegment {

    /** Membership level at or above which an owner is {@code PREMIUM} rather than {@code STANDARD}. */
    private static final int PREMIUM_MIN_LEVEL = 3;

    /** Localities treated as {@code METRO}; any other locality is {@code REGIONAL}. */
    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");

    private OwnerSegment() {
    }

    /**
     * @param membershipLevel the owner's membership level
     * @param locality        the owner's locality, as resolved by {@link CityLocality}
     * @return the {@code <TIER>_<AREA>} segment
     */
    public static String of(int membershipLevel, String locality) {
        String tier = membershipLevel >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }
}

