1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * The duplicate block: rejects a create-owner request that repeats an existing live owner's
11	 * {@link Owner#getIdentityKey() identity key} (same normalized telephone, email and
12	 * phonetically-equal last name), responding 409. Soft-deleted owners are ignored, so a deleted
13	 * owner no longer blocks a new one. Two owners that merely share a last name and postcode but
14	 * differ in telephone have different identity keys and are not blocked here: they are created and
15	 * flagged by {@link AssignOwnerPossibleDuplicate}. A request opting in with
16	 * {@code sharesHousehold} declares the new owner a genuine member and bypasses the block. Runs
17	 * after {@link BuildOwner} (so the entity's telephone, email and name exist) and after
18	 * {@link ValidateOwnerEmailDomain} (so the email-domain blocklist applies first), and before
19	 * {@link SaveOwner} persists a duplicate.
20	 */
21	public class EnsureUniqueIdentity {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            return;
27	        }
28	        if (!Identities.duplicatesOf(ownerRepository, owner).isEmpty()) {
29	            throw new DuplicateIdentityException(owner.getIdentityKey());
30	        }
31	    }
32	}
