1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Immutable structured audit event marking a successful owner creation, serialized to the
5	 * canonical JSON object
6	 * {@code {"seq":..,"ownerId":..,"customerCode":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
7	 *
8	 * <p>The {@code customerCode} field carries the owner's <em>current primary identifier</em>
9	 * (see {@link org.springframework.samples.petclinic.model.Owner#getPrimaryIdentifier()}): the
10	 * customer code today, and whatever unifies it later (e.g. a member id) with no change here.
11	 *
12	 * <p>Emitted by {@link AuditOwnerCreated}; {@code seq} comes from {@link OwnerCreatedEventSequence}
13	 * and increases monotonically across creates.
14	 */
15	public record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel) {
16	
17	    /** The event marker every serialized event carries. */
18	    public static final String EVENT = "OWNER_CREATED";
19	
20	    /** This event as its canonical JSON object, keys in the documented order. */
21	    public String toJson() {
22	        return "{"
23	                + "\"seq\":" + this.seq + ","
24	                + "\"ownerId\":" + this.ownerId + ","
25	                + "\"customerCode\":" + quote(this.customerCode) + ","
26	                + "\"membershipLevel\":" + this.membershipLevel + ","
27	                + "\"event\":" + quote(EVENT)
28	                + "}";
29	    }
30	
31	    private static String quote(String value) {
32	        if (value == null) {
33	            return "null";
34	        }
35	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
36	        for (int i = 0; i < value.length(); i++) {
37	            char c = value.charAt(i);
38	            switch (c) {
39	                case '"' -> sb.append("\\\"");
40	                case '\\' -> sb.append("\\\\");
41	                case '\n' -> sb.append("\\n");
42	                case '\r' -> sb.append("\\r");
43	                case '\t' -> sb.append("\\t");
44	                default -> {
45	                    if (c < 0x20) {
46	                        sb.append(String.format("\\u%04x", (int) c));
47	                    }
48	                    else {
49	                        sb.append(c);
50	                    }
51	                }
52	            }
53	        }
54	        return sb.append('"').toString();
55	    }
56	}
