151	     * owner was created from the flat {@link #getAddress() address} only. The composed
152	     * {@code address} is derived from this and {@link #getAddressLine2()}.
153	     */
154	    public String getAddressLine1() {
155	        return this.addressLine1;
156	    }
157	
