3	import java.util.Comparator;
4	import java.util.Map;
5	import java.util.Optional;
6	import java.util.regex.Pattern;
7	
8	/**
9	 * Converts a raw telephone number to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
10	 * form: a leading '+' followed by 8 to 15 digits.
11	 *
12	 * <p>An explicit leading '+' and country code are kept; otherwise the default country code
13	 * {@code +61} is assumed and a single leading '0' is dropped from the national digits.
14	 * Spaces, dashes and brackets are stripped. So {@code "0412 345 678"} becomes
15	 * {@code "+61412345678"} and {@code "+64 21 123 456"} becomes {@code "+6421123456"}.
16	 */
17	public final class E164PhoneNumber {
18	
19	    /** Country code assumed when the input does not carry an explicit '+' prefix. */
20	    private static final String DEFAULT_COUNTRY_CODE = "61";
21	
22	    /** Separators removed before parsing: spaces, dashes and brackets. */
23	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
24	
25	    /** A well-formed E.164 number: '+' then 8 to 15 digits. */
26	    private static final Pattern E164 = Pattern.compile("\\+[0-9]{8,15}");
27	
28	    /**
29	     * Required national-number length (the digits after the country code) for the country
30	     * codes whose national number is a fixed length. Country codes not listed carry no
31	     * length rule here, so any national length within the generic E.164 bounds is accepted.
32	     */
33	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
34	            "1", 10,   // North American Numbering Plan
35	            "61", 9);  // Australia
36	
37	    private E164PhoneNumber() {
38	    }
39	
40	    /**
41	     * @param raw the caller-supplied telephone, in any common format
42	     * @return the E.164 string, or empty when {@code raw} cannot form a valid one
43	     */
44	    public static Optional<String> toE164(String raw) {
45	        if (raw == null) {
46	            return Optional.empty();
47	        }
48	        String trimmed = raw.trim();
49	        boolean explicitCountryCode = trimmed.startsWith("+");
50	        String cleaned = SEPARATORS.matcher(trimmed).replaceAll("");
51	        String digits;
52	        if (explicitCountryCode) {
53	            digits = cleaned.substring(1); // drop the '+', keep the country code
54	        }
55	        else {
56	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
57	            digits = DEFAULT_COUNTRY_CODE + national;
58	        }
59	        String candidate = "+" + digits;
60	        return E164.matcher(candidate).matches() ? Optional.of(candidate) : Optional.empty();
61	    }
62	
63	    /**
64	     * Formats a stored E.164 number for humans: the country code, a space, then the national
65	     * digits grouped in threes. So {@code "+61412345678"} becomes {@code "+61 412 345 678"}.
66	     *
67	     * <p>The country code is the longest {@link #NATIONAL_NUMBER_LENGTHS known} code that
68	     * prefixes the number, reusing the same country-code facts as the length rule.
69	     *
70	     * @param e164 a normalized E.164 number (a '+' followed by digits), as produced by
71	     *   {@link #toE164}
72	     * @return the human-readable form, or {@code e164} unchanged when it is null, not a
73	     *   well-formed E.164 number, or carries no recognized country code (so the split between
74	     *   country code and national number is unknown)
75	     */
76	    public static String toDisplay(String e164) {
77	        if (e164 == null || !E164.matcher(e164).matches()) {
78	            return e164;
79	        }
80	        String digits = e164.substring(1);
81	        Optional<String> countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
82	                .filter(digits::startsWith)
83	                .max(Comparator.comparingInt(String::length));
84	        if (countryCode.isEmpty()) {
85	            return e164;
86	        }
87	        String national = digits.substring(countryCode.get().length());
88	        return "+" + countryCode.get() + " " + groupInThrees(national);
89	    }
90	
91	    /** Groups a run of digits into space-separated groups of three, left to right. */
92	    private static String groupInThrees(String digits) {
93	        StringBuilder grouped = new StringBuilder();
94	        for (int i = 0; i < digits.length(); i++) {
95	            if (i > 0 && i % 3 == 0) {
96	                grouped.append(' ');
97	            }
98	            grouped.append(digits.charAt(i));
99	        }
100	        return grouped.toString();
101	    }
102	
103	    /**
104	     * Checks a normalized E.164 number's national-number length against its country code.
105	     *
106	     * @param e164 a normalized E.164 number (a '+' followed by digits), as produced by
107	     *   {@link #toE164}
108	     * @return {@code true} when the national number has the length its country code
109	     *   requires, or the country code has no fixed-length rule; {@code false} when the
110	     *   length is wrong for a country code with a known requirement
111	     */
112	    public static boolean hasValidNationalNumberLength(String e164) {
113	        if (e164 == null || !e164.startsWith("+")) {
114	            return false;
115	        }
116	        String digits = e164.substring(1);
117	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
118	                .filter(entry -> digits.startsWith(entry.getKey()))
119	                .max(Comparator.comparingInt(entry -> entry.getKey().length()))
120	                .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
121	                .orElse(true);
122	    }
123	}
