26	     * The existing live owners that share a household (same last name and postcode) with the
27	     * given fields. Soft-deleted owners are excluded, so a deleted owner no longer blocks or
28	     * flags a new one. Empty when no postcode is supplied.
29	     */
30	    static List<Owner> membersOf(OwnerRepository ownerRepository, String lastName, String postcode) {
31	        String householdId = idFor(lastName, postcode);
32	        if (householdId == null) {
33	            return List.of();
34	        }
35	        return ownerRepository.findByLastName(lastName).stream()
36	                .filter(owner -> !owner.isDeleted())
37	                .filter(owner -> householdId.equals(idFor(owner.getLastName(), owner.getPostcode())))
38	                .toList();
39	    }
40	
41	    /**
42	     * The highest {@link Owner#getMembershipLevel() membership level} currently held by an
43	     * existing member of the household (same last name and postcode), or empty when the
44	     * household has no existing members.
45	     */
46	    static OptionalInt maxMembershipLevel(OwnerRepository ownerRepository, String lastName, String postcode) {
47	        return membersOf(ownerRepository, lastName, postcode).stream()
48	                .mapToInt(Owner::getMembershipLevel)
49	                .max();
50	    }
51	
52	    /**
53	     * The stable identifier shared by every owner at the given last name and postcode: the
54	     * first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' +
55	     * postcode}. Returns {@code null} when no postcode is supplied, since an owner without a
56	     * postcode has no household.
57	     */
58	    static String idFor(String lastName, String postcode) {
59	        if (postcode == null || postcode.isBlank()) {
60	            return null;
61	        }
62	        return sha256Hex(normalizeName(lastName) + "|" + postcode).substring(0, 12).toUpperCase();
63	    }
64	
65	    private static String normalizeName(String value) {
66	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
67	    }
68	
69	    private static String sha256Hex(String value) {
70	        try {
71	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
72	            StringBuilder sb = new StringBuilder(digest.length * 2);
73	            for (byte b : digest) {
74	                sb.append(String.format("%02x", b));
75	            }
76	            return sb.toString();
77	        }
78	        catch (NoSuchAlgorithmException e) {
79	            throw new IllegalStateException("SHA-256 not available", e);
80	        }
81	    }
82	}
